  // Straight-line unique-named const stages, mirroring the lisp let* chain.
  // unrolled binary search stages (no loop-carried string mutation)
  const lo0 = GRID_LO;
  const hi0 = GRID_HI;
  const mid1 = u128MulDiv(u128.add(lo0, hi0), "1", "2");
  const go_up1 = u128.lt(sum_gross(mid1), deposit);
  const lo1 = go_up1 ? u128.add(mid1, "1") : lo0;
  const hi1 = go_up1 ? hi0 : mid1;
  const mid2 = u128MulDiv(u128.add(lo1, hi1), "1", "2");
  const go_up2 = u128.lt(sum_gross(mid2), deposit);
