  const mid28 = u128MulDiv(u128.add(lo27, hi27), "1", "2");
  const go_up28 = u128.lt(sum_gross(mid28), deposit);
  const lo28 = go_up28 ? u128.add(mid28, "1") : lo27;
  const hi28 = go_up28 ? hi27 : mid28;
  const mid29 = u128MulDiv(u128.add(lo28, hi28), "1", "2");
