  const lo30 = go_up30 ? u128.add(mid30, "1") : lo29;
  const hi30 = go_up30 ? hi29 : mid30;
  const mid31 = u128MulDiv(u128.add(lo30, hi30), "1", "2");
  const go_up31 = u128.lt(sum_gross(mid31), deposit);
  const lo31 = go_up31 ? u128.add(mid31, "1") : lo30;
  const hi31 = go_up31 ? hi30 : mid31;
  const mid32 = u128MulDiv(u128.add(lo31, hi31), "1", "2");
  const go_up32 = u128.lt(sum_gross(mid32), deposit);
  const lo32 = go_up32 ? u128.add(mid32, "1") : lo31;
