function credit(failTag: string): string {
  const who = sget("sp:who");
  const out = near.promiseResult(0);
  if (out === "") { fail(failTag); }
  const pk = "paid:" + who;
  const total = u128.add(sget(pk), out);
  sput(pk, total);
  return total;
}

export function on0(): string {
  return credit("ERR_P0");
}
export function on1(): string {
  return credit("ERR_P1");
}
export function on2(): string {
  const total = credit("ERR_P2");
  near.log("splt3 total=" + total);
  return total;
}

export function get_paid(): string {
  return sget("paid:" + near.predecessorAccountId());
}

export function get_split(): string {
  return sget("s:s0") + "," + sget("s:s1") + "," + sget("s:s2");
}
